package lifequest.classroom;

import lifequest.database.AssignmentDAO;
import lifequest.database.AssignmentDAO.Assignment;
import lifequest.database.AssignmentDAO.Submission;
import lifequest.model.User;
import lifequest.ui.Style;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.text.SimpleDateFormat;
import java.util.*;

/** Role-aware assignment management and leaderboard screen. */
public class ClassroomPanel extends JPanel {
    private final User user; private final AssignmentDAO dao=new AssignmentDAO(); private final JPanel body=new JPanel(new BorderLayout(12,12));
    public ClassroomPanel(User user){this.user=user;setLayout(new BorderLayout());setBackground(Style.BACKGROUND);setBorder(new EmptyBorder(24,26,24,26));add(Style.title(user.isAdmin()?"Classroom · Teacher Console":"Classroom · Assignments"),BorderLayout.NORTH);body.setOpaque(false);add(body,BorderLayout.CENTER);refresh();}
    private void refresh(){body.removeAll();JTabbedPane tabs=new JTabbedPane();tabs.setFont(new Font("Segoe UI",Font.BOLD,13));if(user.isAdmin()){tabs.addTab("Assignments",adminAssignments());tabs.addTab("Review submissions",reviewPanel());tabs.addTab("Leaderboard",leaderboardPanel());}else{tabs.addTab("My assignments",studentAssignments());tabs.addTab("Class leaderboard",leaderboardPanel());}body.add(tabs,BorderLayout.CENTER);body.revalidate();body.repaint();}
    private JPanel adminAssignments(){JPanel p=base();JPanel form=Style.card();form.setLayout(new GridLayout(0,2,10,9));JTextField title=new JTextField(),due=new JTextField();JTextArea desc=new JTextArea(3,20);JComboBox<String> diff=new JComboBox<>(new String[]{"Easy","Medium","Hard","Epic"});JSpinner points=new JSpinner(new SpinnerNumberModel(20,1,1000,5));form.add(Style.label("Assignment title"));form.add(title);form.add(Style.label("Difficulty"));form.add(diff);form.add(Style.label("Points"));form.add(points);form.add(Style.label("Due date (YYYY-MM-DD, optional)"));form.add(due);form.add(Style.label("Instructions"));form.add(new JScrollPane(desc));JButton create=Style.button("Publish assignment");form.add(new JLabel());form.add(create);create.addActionListener(e->{if(title.getText().trim().isEmpty()){msg("Enter an assignment title.");return;}java.sql.Date d=null;if(!due.getText().trim().isEmpty())try{d=java.sql.Date.valueOf(due.getText().trim());}catch(Exception ex){msg("Use date format YYYY-MM-DD.");return;}if(dao.create(title.getText().trim(),desc.getText().trim(),String.valueOf(diff.getSelectedItem()),(Integer)points.getValue(),d,user.getId())){msg("Assignment published!");refresh();}else msg("Could not publish. Check database setup.");});p.add(form,BorderLayout.NORTH);p.add(new JScrollPane(tableAssignments(dao.allAssignments(),false)),BorderLayout.CENTER);return p;}
    private JPanel studentAssignments(){JPanel p=base();JTable t=table(new String[]{"ID","Assignment","Difficulty","Points","Due date","Status"});for(Assignment a:dao.assignmentsForStudent(user.getId()))((DefaultTableModel)t.getModel()).addRow(new Object[]{a.id,a.title,a.difficulty,a.points,a.dueDate==null?"—":a.dueDate,a.status});JButton submit=Style.button("Submit selected assignment");submit.addActionListener(e->{int row=t.getSelectedRow();if(row<0){msg("Select an assignment first.");return;}int id=Integer.parseInt(t.getValueAt(row,0).toString());String status=t.getValueAt(row,5).toString();if("APPROVED".equalsIgnoreCase(status)){msg("This assignment is already approved.");return;}String note=JOptionPane.showInputDialog(this,"Enter a short submission note or work summary:");if(note!=null&&dao.submit(id,user.getId(),note.trim())){msg("Submitted for teacher review.");refresh();}else if(note!=null)msg("Submission failed. Check database setup.");});p.add(new JScrollPane(t),BorderLayout.CENTER);p.add(submit,BorderLayout.SOUTH);return p;}
    private JPanel reviewPanel(){JPanel p=base();JTable t=table(new String[]{"ID","Student","Assignment","Status","Points","Submitted"});for(Submission s:dao.submissions())((DefaultTableModel)t.getModel()).addRow(new Object[]{s.id,s.student,s.assignment,s.status,s.points,s.submittedAt});JPanel buttons=new JPanel(new FlowLayout(FlowLayout.LEFT));buttons.setOpaque(false);JButton approve=Style.button("Approve & award points"),reject=Style.secondaryButton("Reject submission");buttons.add(approve);buttons.add(reject);approve.addActionListener(e->review(t,true));reject.addActionListener(e->review(t,false));p.add(new JScrollPane(t),BorderLayout.CENTER);p.add(buttons,BorderLayout.SOUTH);return p;}
    private void review(JTable t,boolean approve){int row=t.getSelectedRow();if(row<0){msg("Select a submission first.");return;}int id=Integer.parseInt(t.getValueAt(row,0).toString());if(dao.review(id,approve)){msg(approve?"Approved. Assignment points have been awarded.":"Submission rejected.");refresh();}else msg("Review could not be saved. It may already have been reviewed.");}
    private JPanel leaderboardPanel(){JPanel p=base();JTable t=table(new String[]{"Rank","Student","Total points","Approved assignments"});int rank=1;for(String[] row:dao.leaderboard())((DefaultTableModel)t.getModel()).addRow(new Object[]{rank++,row[0],row[1],row[2]});p.add(new JScrollPane(t),BorderLayout.CENTER);return p;}
    private JTable tableAssignments(java.util.List<Assignment> list,boolean student){JTable t=table(new String[]{"ID","Assignment","Difficulty","Points","Due date"});for(Assignment a:list)((DefaultTableModel)t.getModel()).addRow(new Object[]{a.id,a.title,a.difficulty,a.points,a.dueDate==null?"—":a.dueDate});return t;}
    private JTable table(String[] cols){DefaultTableModel m=new DefaultTableModel(cols,0){public boolean isCellEditable(int r,int c){return false;}};JTable t=new JTable(m);t.setRowHeight(30);t.setFont(new Font("Segoe UI",Font.PLAIN,13));t.getTableHeader().setFont(new Font("Segoe UI",Font.BOLD,12));return t;}
    private JPanel base(){JPanel p=new JPanel(new BorderLayout(12,12));p.setOpaque(false);return p;}
    private void msg(String s){JOptionPane.showMessageDialog(this,s,"LifeQuest",JOptionPane.INFORMATION_MESSAGE);}
}
